# Custom REST Service in Dynamics AX (X++)

## Overview

Creating a custom REST service in Dynamics 365 Finance & Operations (D365FO) involves creating a **Service Contract**, **Data Contract**, and **Service Class**, then exposing them via a **Service Node** in the AOT.

---

## Step 1: Create the Data Contract (Request/Response)

```xpp
/// <summary>
/// Data contract for Customer information (Response)
/// </summary>
[DataContractAttribute]
class CustInfoResponseContract
{
    str     custAccount;
    str     custName;
    str     custGroup;
    str     currency;
    str     email;
    boolean success;
    str     errorMessage;

    [DataMemberAttribute('CustomerAccount')]
    public str parmCustAccount(str _custAccount = custAccount)
    {
        custAccount = _custAccount;
        return custAccount;
    }

    [DataMemberAttribute('CustomerName')]
    public str parmCustName(str _custName = custName)
    {
        custName = _custName;
        return custName;
    }

    [DataMemberAttribute('CustomerGroup')]
    public str parmCustGroup(str _custGroup = custGroup)
    {
        custGroup = _custGroup;
        return custGroup;
    }

    [DataMemberAttribute('Currency')]
    public str parmCurrency(str _currency = currency)
    {
        currency = _currency;
        return currency;
    }

    [DataMemberAttribute('Email')]
    public str parmEmail(str _email = email)
    {
        email = _email;
        return email;
    }

    [DataMemberAttribute('Success')]
    public boolean parmSuccess(boolean _success = success)
    {
        success = _success;
        return success;
    }

    [DataMemberAttribute('ErrorMessage')]
    public str parmErrorMessage(str _errorMessage = errorMessage)
    {
        errorMessage = _errorMessage;
        return errorMessage;
    }
}
```

