## Step 2: Create the Service Class (Business Logic)

```xpp
/// <summary>
/// Custom REST Service class for Customer operations
/// </summary>
class CustCustomRestService
{
    /// <summary>
    /// GET: Retrieve customer information by account number
    /// </summary>
    /// <param name="_custAccount">Customer account number</param>
    /// <returns>CustInfoResponseContract with customer details</returns>
    [AifCollectionTypeAttribute('return', Types::Class)]
    public CustInfoResponseContract getCustomerByAccount(str _custAccount)
    {
        CustInfoResponseContract    response = new CustInfoResponseContract();
        CustTable                   custTable;

        try
        {
            if (!_custAccount)
            {
                throw error("Customer account number is required.");
            }

            select firstonly custTable
                where custTable.AccountNum == _custAccount;

            if (custTable)
            {
                DirPartyTable dirPartyTable = DirPartyTable::findRec(custTable.Party);

                response.parmCustAccount(custTable.AccountNum);
                response.parmCustName(dirPartyTable.Name);
                response.parmCustGroup(custTable.CustGroup);
                response.parmCurrency(custTable.Currency);
                response.parmEmail(this.getPrimaryEmail(custTable.Party));
                response.parmSuccess(true);
            }
            else
            {
                response.parmSuccess(false);
                response.parmErrorMessage(strFmt("Customer '%1' not found.", _custAccount));
            }
        }
        catch (Exception::Error)
        {
            response.parmSuccess(false);
            response.parmErrorMessage(infolog.text(infologLine()));
        }

        return response;
    }

    /// <summary>
    /// GET: Retrieve all customers by customer group
    /// </summary>
    /// <param name="_custGroupId">Customer group ID</param>
    /// <returns>CustListResponseContract with list of customers</returns>
    [AifCollectionTypeAttribute('return', Types::Class)]
    public CustListResponseContract getCustomersByGroup(str _custGroupId)
    {
        CustListResponseContract    response = new CustListResponseContract();
        List                        customerList = new List(Types::Class);
        CustTable                   custTable;
        int                         recordCount = 0;

        try
        {
            if (!_custGroupId)
            {
                throw error("Customer group ID is required.");
            }

            while select custTable
                where custTable.CustGroup == _custGroupId
            {
                CustInfoResponseContract custInfo = new CustInfoResponseContract();
                DirPartyTable dirPartyTable = DirPartyTable::findRec(custTable.Party);

                custInfo.parmCustAccount(custTable.AccountNum);
                custInfo.parmCustName(dirPartyTable.Name);
                custInfo.parmCustGroup(custTable.CustGroup);
                custInfo.parmCurrency(custTable.Currency);
                custInfo.parmEmail(this.getPrimaryEmail(custTable.Party));
                custInfo.parmSuccess(true);

                customerList.addEnd(custInfo);
                recordCount++;
            }

            response.parmCustomers(customerList);
            response.parmTotalRecords(recordCount);
            response.parmSuccess(true);
        }
        catch (Exception::Error)
        {
            response.parmSuccess(false);
            response.parmErrorMessage(infolog.text(infologLine()));
        }

        return response;
    }

    /// <summary>
    /// POST: Create a new customer record
    /// </summary>
    /// <param name="_request">CustCreateRequestContract with customer data</param>
    /// <returns>CustInfoResponseContract with created customer details</returns>
    [AifCollectionTypeAttribute('return', Types::Class)]
    public CustInfoResponseContract createCustomer(CustCreateRequestContract _request)
    {
        CustInfoResponseContract response = new CustInfoResponseContract();

        try
        {
            // Validate required fields
            if (!_request.parmCustAccount())
            {
                throw error("Customer account is required.");
            }

            if (!_request.parmCustName())
            {
                throw error("Customer name is required.");
            }

            if (!_request.parmCustGroup())
            {
                throw error("Customer group is required.");
            }

            // Check if customer already exists
            if (CustTable::find(_request.parmCustAccount()))
            {
                throw error(strFmt("Customer '%1' already exists.", _request.parmCustAccount()));
            }

            // Validate customer group exists
            if (!CustGroup::find(_request.parmCustGroup()))
            {
                throw error(strFmt("Customer group '%1' does not exist.", _request.parmCustGroup()));
            }

            ttsbegin;

            // Create Party (DirPartyTable)
            DirPartyTable dirPartyTable;
            dirPartyTable.Name = _request.parmCustName();
            dirPartyTable.insert();

            // Create Customer
            CustTable custTable;
            custTable.AccountNum    = _request.parmCustAccount();
            custTable.Party         = dirPartyTable.RecId;
            custTable.CustGroup     = _request.parmCustGroup();
            custTable.Currency      = _request.parmCurrency()
                                        ? _request.parmCurrency()
                                        : Ledger::accountingCurrency();
            custTable.insert();

            // Create email if provided
            if (_request.parmEmail())
            {
                this.createElectronicAddress(
                    dirPartyTable.RecId,
                    _request.parmEmail(),
                    LogisticsElectronicAddressMethodType::Email
                );
            }

            ttscommit;

            // Build response
            response.parmCustAccount(custTable.AccountNum);
            response.parmCustName(dirPartyTable.Name);
            response.parmCustGroup(custTable.CustGroup);
            response.parmCurrency(custTable.Currency);
            response.parmEmail(_request.parmEmail());
            response.parmSuccess(true);

            info(strFmt("Customer '%1' created successfully.", custTable.AccountNum));
        }
        catch (Exception::Error)
        {
            response.parmSuccess(false);
            response.parmErrorMessage(infolog.text(infologLine()));
        }

        return response;
    }

    /// <summary>
    /// PUT: Update an existing customer record
    /// </summary>
    /// <param name="_request">CustCreateRequestContract with updated customer data</param>
    /// <returns>CustInfoResponseContract with updated customer details</returns>
    [AifCollectionTypeAttribute('return', Types::Class)]
    public CustInfoResponseContract updateCustomer(CustCreateRequestContract _request)
    {
        CustInfoResponseContract response = new CustInfoResponseContract();

        try
        {
            if (!_request.parmCustAccount())
            {
                throw error("Customer account is required for update.");
            }

            CustTable custTable = CustTable::find(_request.parmCustAccount(), true);

            if (!custTable)
            {
                throw error(strFmt("Customer '%1' not found.", _request.parmCustAccount()));
            }

            ttsbegin;

            // Update customer fields
            if (_request.parmCustGroup())
            {
                if (!CustGroup::find(_request.parmCustGroup()))
                {
                    throw error(strFmt("Customer group '%1' does not exist.",
                                        _request.parmCustGroup()));
                }
                custTable.CustGroup = _request.parmCustGroup();
            }

            if (_request.parmCurrency())
            {
                custTable.Currency = _request.parmCurrency();
            }

            custTable.update();

            // Update party name
            if (_request.parmCustName())
            {
                DirPartyTable dirPartyTable =
                    DirPartyTable::findRec(custTable.Party, true);

                if (dirPartyTable)
                {
                    dirPartyTable.Name = _request.parmCustName();
                    dirPartyTable.update();
                }
            }

            ttscommit;

            // Build response
            DirPartyTable dirParty = DirPartyTable::findRec(custTable.Party);
            response.parmCustAccount(custTable.AccountNum);
            response.parmCustName(dirParty.Name);
            response.parmCustGroup(custTable.CustGroup);
            response.parmCurrency(custTable.Currency);
            response.parmEmail(this.getPrimaryEmail(custTable.Party));
            response.parmSuccess(true);
        }
        catch (Exception::Error)
        {
            response.parmSuccess(false);
            response.parmErrorMessage(infolog.text(infologLine()));
        }

        return response;
    }

    /// <summary>
    /// DELETE: Delete a customer record
    /// </summary>
    /// <param name="_custAccount">Customer account number to delete</param>
    /// <returns>CustInfoResponseContract with deletion result</returns>
    [AifCollectionTypeAttribute('return', Types::Class)]
    public CustInfoResponseContract deleteCustomer(str _custAccount)
    {
        CustInfoResponseContract response = new CustInfoResponseContract();

        try
        {
            if (!_custAccount)
            {
                throw error("Customer account number is required.");
            }

            CustTable custTable = CustTable::find(_custAccount, true);

            if (!custTable)
            {
                throw error(strFmt("Customer '%1' not found.", _custAccount));
            }

            // Check for open transactions before deletion
            if (custTable.openBalanceMST() != 0)
            {
                throw error(strFmt(
                    "Cannot delete customer '%1'. Open balance exists.", _custAccount));
            }

            ttsbegin;

            response.parmCustAccount(custTable.AccountNum);
            custTable.delete();

            ttscommit;

            response.parmSuccess(true);
            response.parmErrorMessage(strFmt(
                "Customer '%1' deleted successfully.", _custAccount));
        }
        catch (Exception::Error)
        {
            response.parmSuccess(false);
            response.parmErrorMessage(infolog.text(infologLine()));
        }

        return response;
    }

    /// <summary>
    /// Helper: Get primary email for a party
    /// </summary>
    private str getPrimaryEmail(DirPartyRecId _partyRecId)
    {
        LogisticsElectronicAddress electronicAddress;

        select firstonly Locator from electronicAddress
            exists join LogisticsLocation
            where electronicAddress.Type == LogisticsElectronicAddressMethodType::Email
               && electronicAddress.IsPrimary == NoYes::Yes;

        // Alternative approach using party
        DirParty dirParty = DirParty::constructFromPartyRecId(_partyRecId);
        LogisticsElectronicAddress primaryEmail =
            dirParty.getPrimaryElectronicAddress(
                LogisticsElectronicAddressMethodType::Email);

        return primaryEmail ? primaryEmail.Locator : '';
    }

    /// <summary>
    /// Helper: Create an electronic address for a party
    /// </summary>
    private void createElectronicAddress(
        DirPartyRecId                       _partyRecId,
        str                                 _locator,
        LogisticsElectronicAddressMethodType _type)
    {
        DirParty                    dirParty;
        LogisticsElectronicAddress  electronicAddress;

        dirParty = DirParty::constructFromPartyRecId(_partyRecId);

        electronicAddress.Type       = _type;
        electronicAddress.Locator    = _locator;
        electronicAddress.IsPrimary  = NoYes::Yes;
        electronicAddress.insert();

        dirParty.addElectronicAddress(electronicAddress);
    }
}
```

