/// Service contract interface defining the operations exposed via REST
/// </summary>
[ServiceGroupAttribute('CustCustomServiceGroup')]
class CustCustomRestServiceContract
{
    // This class is used for service group decoration.
    // The actual service operations are defined in CustCustomRestService
    // and referenced via the AOT Service node.
}
