    <Name>CustCustomRestService</Name>
    <Description>Custom REST Service for Customer Operations</Description>
    <ExternalName>CustCustomRestService</ExternalName>
    <Class>CustCustomRestService</Class>
    <Operations>
        <AxServiceOperation>
            <Name>getCustomerByAccount</Name>
        </AxServiceOperation>
        <AxServiceOperation>
            <Name>getCustomersByGroup</Name>
        </AxServiceOperation>
        <AxServiceOperation>
            <Name>createCustomer</Name>
        </AxServiceOperation>
        <AxServiceOperation>
            <Name>updateCustomer</Name>
        </AxServiceOperation>
        <AxServiceOperation>
            <Name>deleteCustomer</Name>
        </AxServiceOperation>
    </Operations>
</AxService>
```

### 4b. Service Group Definition (`CustCustomServiceGroup.xml`)

```xml
<?xml version="1.0" encoding="utf-8"?>
<AxServiceGroup xmlns:i="http://www.w3.org/2001/XMLSchema-instance">
    <Name>CustCustomServiceGroup</Name>
    <Description>Custom REST Service Group for Customer Operations</Description>
    <AutoDeploy>Yes</AutoDeploy>
    <Services>
        <AxServiceGroupMember>
            <Name>CustCustomRestService</Name>
            <Service>CustCustomRestService</Service>
        </AxServiceGroupMember>
    </Services>
</AxServiceGroup>
```

